namespace Unwalked.Domain.Feedback;

/// <summary>
/// One anonymous reaction to a recommendation. Holds no user id and no location.
/// </summary>
public sealed class RecommendationFeedback
{
    public long Id { get; set; }

    /// <summary>
    /// Identifier generated by the client, unique per event, which makes retries idempotent.
    /// </summary>
    public Guid EventId { get; set; }

    public RecommendationType RecommendationType { get; set; }

    public FeedbackAction Action { get; set; }

    public int? CategoryId { get; set; }

    /// <summary>
    /// Day the server received the event. The time is not stored so reactions cannot be linked to sessions.
    /// </summary>
    public DateOnly ReceivedOn { get; set; }
}
